const check:(value:unknown,message:string)=>asserts value=(value,message)=>{if(!value)throw Error(message)};
const count=(text:string,needle:string)=>text.split(needle).length-1;
const ordered=(text:string,needles:string[])=>{let cursor=-1;for(const needle of needles){const next=text.indexOf(needle,cursor+1);check(next>cursor,'ordering '+needle);cursor=next}};
