 for(const forbidden of ['process.env','Bun.env','Deno.env','child_process','exec(','spawn(','console.error','console.log(body','unlink(lockPath'])check(!entry.includes(forbidden),'entry secret/process boundary '+forbidden);
 check(entry.includes("gate.status==='m78_readonly_recovery2_execution_admitted'")&&entry.includes('gate.applicationPostRequests===0')&&entry.includes('gate.workspaceId===input.roster.workspaceId'),'entry exact admission');
 check(entry.includes("failedRecoveryJournalText:'.superpowers/m78-continuation4-readonly-recovery.jsonl'")&&entry.includes("failedRecoveryDiagnosticText:'.superpowers/m78-continuation4-readonly-recovery-diagnostics.jsonl'")&&entry.includes("failedRecoveryReviewText:'evaluations/research-qa/m78-readonly-failure-review2-result.json'"),'preserved failure inputs');
 ordered(entry,['const gateText=await readFile(gatePath','for(const p of gate.pins)','const runtime=JSON.parse','const sourceText=await readFile','const loaded=Object.fromEntries','await verifyM78ReadonlyRecovery2PreAuth(admission)','const expectedSubjects=Object.fromEntries','gate.privateConfigSha256','for(const p of Object.values(paths))','lock=await open(lockPath','runM78Continuation4ReadonlyRecovery2']);
 check(entry.includes("runtime.status==='m78_get_route_deployed_runtime_verified'")&&entry.includes('runtime.ready.schemaVersion===21')&&entry.includes('age>=0&&age<15*60*1000')&&entry.includes('source.runtime.commit===runtime.commit&&source.runtime.deploymentId===runtime.deploymentId'),'runtime/source binding');
 check(entry.includes('for(const p of gate.pins)check(sha(await readFile(p.path))===p.sha256)')&&entry.includes('currentSourcePins:source.sourcePins')&&entry.includes('load:async(p:string)=>new Uint8Array(await readFile(p))'),'source pin rehash input');
 check(entry.includes("gate.privateConfigSha256==='"+pins.privateConfigSha256+"'")&&entry.includes("sha(await readFile('C:/Users/nimab/Neuvetra/m63-runtime/recovery/m63-private-config.json.dpapi'))===gate.privateConfigSha256"),'entry encrypted config binding');
 check(entry.includes("check(Object.values(paths).includes(p as any))")&&entry.includes("exclusive?'wx':'a'")&&entry.includes('await f.sync()'),'bounded exclusive IO');
 check(entry.includes("open(lockPath,'wx',0o600)")&&entry.includes("lock.writeFile('{\"profile\":\"m78-readonly-recovery2-exclusive-v1\"}\\n')")&&entry.includes('await lock.sync()')&&entry.includes('Keep the lock as a durable no-replay marker'),'durable recovery2 lock');
 check(entry.includes("AUTH+'/auth/v1/token?grant_type=password'")&&entry.includes("AUTH+'/auth/v1/logout?scope=local'")&&!entry.includes('/logout?scope=global'),'fixed auth and local logout');
 check(entry.includes("runM72Journey({...input,mode:'baseline'}")&&entry.includes('load:async()=>null')&&entry.includes('save:async value=>{captured=value}')&&entry.includes('result.applicationPostRequests===0')&&entry.includes('result.allCreatedAuthSessionsClosed===true')&&entry.includes('canonical(captured?.baseline)===canonical(expected)'),'read-only legacy verification');
