 for(const forbidden of ['$env:','Write-Host','$errors.Result','Write-Output $errors','Remove-Item','Start-Process','Invoke-WebRequest','Invoke-RestMethod'])check(!wrapper.includes(forbidden),'wrapper secret/process boundary '+forbidden);
 check(wrapper.includes("[ValidatePattern('^[a-f0-9]{64}$')]")&&wrapper.includes("path='.superpowers/m78-readonly-recovery2-execution-admission.json';sha256=$AdmissionSha256"),'safe exact admission input');
