 for(const required of ['.superpowers/m78-private-readonly-recovery2.ps1','.superpowers/m78-readonly-recovery2-entry.ts','tools/staging/check-m78-continuation4-readonly-recovery2.ts'])check(wrapper.includes(required),'required source '+required);
